head.script:
scwin.fireDbClick = function(id) {
    var node = WebSquare.wUnit.getDomById(id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.___isCheckLog = function() {
    return WebSquare.logger.getErrorLog() == "";
}
scwin.__isCheckYearMonth = function() {
    var d = new Date();
    if (d.getMonth() + 1 < 10)
        return d.getFullYear() + "-" + (d.getMonth().legnth == 2 ? d.getMonth() : '0' + (d.getMonth() + 1));
    else
        return d.getFullYear() + "-" + (d.getMonth().legnth == 2 ? d.getMonth() : +(d.getMonth() + 1));
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'name2'항목을 마우스로 더블클릭 한다.
    //1. After running the sample, double-click the 'name2' item with the mouse.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.fireDbClick('wq_uuid_3_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. edit모드로 변경되고 우측에 달력아이콘이 보여진다. 
    //1. Change to edit mode and a calendar icon is displayed on the right.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_'+$p.id+'wq_uuid_3__col2').css('display')", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 달력아이콘을 클릭하여 현재년월(201805)을 선택하고 마우스를 다른곳 클릭한다.
    //2. Click the calendar icon, select the current year (201805), and click the mouse somewhere else.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'wq_uuid_3__col2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#G_'+$p.id+'wq_uuid_3__col2_calendar_picker_content').find('.active').click()");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'wq_uuid_3__col2_calendar_picker_cell_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_3_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 2018-05값이 보여진다.
    //2. The value 2018-05 is displayed.
    //WebSquare.wUnit.addCommand("assert", "scwin.__isCheckYearMonth() == WebSquare.wUnit.getDomById('wq_uuid_3_cell_0_1').innerText", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. ctrl + 마우스 우클릭 > 로그보기를 확인한다.
    //3. Check the ctrl + right-click> log view.
    //Verify 3. 정상로그가 보여진다.(이전에는 아래와 같은 로그오류 발생) Cannot read property "focus" of null
    //3. The normal log is displayed.(Previously the following log error) Can not read property "focus" of null
    WebSquare.wUnit.addCommand("assert", "scwin.___isCheckLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    dataList1.insertRow();
